<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { NButton, NInput, NInputNumber, NSelect, NPagination, NTag, NModal, NAlert, useMessage } from 'naive-ui';
import { ShieldCheck } from 'lucide-vue-next';
import { api, json } from '../api';
import { useAdminTicketsStore } from '../stores/admin-tickets.store';
import { dateLabel, statusLabel, type Page, type Report, type User, type Ticket } from '../types';
const message = useMessage(); const tickets = useAdminTicketsStore();
const tab = ref('tickets'); const busy = ref(false);
const reports = ref<Page<Report>>({ items: [], total: 0, page: 1 }); const reportPage = ref(1); const reportUser = ref('');
const users = ref<User[]>([]); const userSearch = ref('');
const anomalies = ref<{ jumps: { id: string; userId: string; load: number; previousLoad: number; createdAt: string }[]; spam: { userId: string; count: number }[] }>({ jumps: [], spam: [] });
const logs = ref<{ id: string; action: string; targetId: string; createdAt: string; admin: User; details: unknown }[]>([]);
const modal = ref(false); const reason = ref(''); const delta = ref<number | null>(2); const target = ref<User | null>(null);
const review = ref<{ report: Report; status: string } | null>(null);
const ticketModal = ref(false); const activeTicket = ref<Ticket | null>(null); const ticketStatus = ref('IN_PROGRESS'); const reply = ref('');
async function fetchReports() { reports.value = await api<Page<Report>>(`/admin/reports?page=${reportPage.value}&userId=${encodeURIComponent(reportUser.value)}`.replace(/&userId=$/, '')); }
async function refresh() { busy.value = true; try { await Promise.all([tickets.fetchTickets(), fetchReports(), fetchUsers(), api<typeof anomalies.value>('/admin/anomalies').then(r => { anomalies.value = r; }), api<typeof logs.value>('/admin/logs').then(r => { logs.value = r; })]); } catch (e) { message.error((e as Error).message); } finally { busy.value = false; } }
async function fetchUsers() { users.value = await api<User[]>(`/admin/users?q=${encodeURIComponent(userSearch.value)}`); }
async function safe(action: () => Promise<unknown>) { try { await action(); } catch (e) { message.error((e as Error).message); } }
function moderate(report: Report, status: string) { review.value = { report, status }; target.value = null; reason.value = ''; modal.value = true; }
function adjust(user: User) { target.value = user; review.value = null; reason.value = ''; modal.value = true; }
async function saveModeration() {
  busy.value = true;
  try { if (review.value) await api(`/admin/reports/${review.value.report.id}`, json({ status: review.value.status, reason: reason.value }, 'PATCH')); else if (target.value) await api(`/admin/users/${target.value.id}/rating`, json({ delta: delta.value, reason: reason.value }, 'PATCH')); modal.value = false; message.success('Изменения сохранены в журнале'); await refresh(); }
  catch (e) { message.error((e as Error).message); } finally { busy.value = false; }
}
function editTicket(ticket: Ticket) { activeTicket.value = ticket; ticketStatus.value = ticket.status; reply.value = ticket.reply ?? ''; ticketModal.value = true; }
async function saveTicket() { if (!activeTicket.value) return; busy.value = true; try { await tickets.update(activeTicket.value.id, ticketStatus.value, reply.value); ticketModal.value = false; message.success('Обращение обновлено'); } catch (e) { message.error((e as Error).message); } finally { busy.value = false; } }
async function userHistory(user: User) { reportUser.value = user.id; reportPage.value = 1; tab.value = 'reports'; await safe(fetchReports); }
onMounted(refresh);
</script>
<template>
  <section class="content-page"><div class="page-intro"><div><p class="eyebrow"><ShieldCheck :size="14" /> ЦЕНТР МОДЕРАЦИИ</p><h1>Доверие — в деталях.</h1><p class="page-intro__description">Обращения, проверка отметок и репутация пассажиров.</p></div><NButton :loading="busy" @click="refresh">Обновить данные</NButton></div>
    <nav class="admin-tabs" aria-label="Разделы модерации"><button v-for="item in [{ id: 'tickets', title: 'Обращения' }, { id: 'reports', title: 'Отметки' }, { id: 'users', title: 'Пассажиры' }, { id: 'anomalies', title: 'Аномалии' }, { id: 'logs', title: 'Журнал' }]" :key="item.id" :class="['admin-tabs__button', { 'admin-tabs__button_active': tab === item.id }]" @click="tab = item.id">{{ item.title }}</button></nav>
    <div class="surface">
      <template v-if="tab === 'tickets'"><div class="admin-toolbar"><h2>Обращения <span class="muted">{{ tickets.total }}</span></h2><NSelect v-model:value="tickets.status" clearable placeholder="Все статусы" :options="['OPEN', 'IN_PROGRESS', 'CLOSED'].map(value => ({ value, label: statusLabel[value] }))" @update:value="tickets.page = 1; safe(tickets.fetchTickets)" /><NSelect v-model:value="tickets.type" clearable placeholder="Все типы" :options="[{ label: 'Жалобы', value: 'COMPLAINT' }, { label: 'Вопросы', value: 'QUESTION' }]" @update:value="tickets.page = 1; safe(tickets.fetchTickets)" /></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Тема</th><th>Пассажир</th><th>Тип</th><th>Статус</th><th></th></tr></thead><tbody><tr v-for="ticket in tickets.items" :key="ticket.id"><td>{{ ticket.subject }}<small>{{ dateLabel(ticket.createdAt) }}</small></td><td>{{ ticket.user?.name }}</td><td>{{ ticket.type === 'QUESTION' ? 'Вопрос' : 'Жалоба' }}</td><td><NTag size="small">{{ statusLabel[ticket.status] }}</NTag></td><td><NButton size="small" @click="editTicket(ticket)">Открыть</NButton></td></tr></tbody></table></div><p v-if="!tickets.items.length" class="empty-state">Обращений по выбранным фильтрам нет.</p><NPagination v-model:page="tickets.page" :item-count="tickets.total" :page-size="25" @update:page="safe(tickets.fetchTickets)" /></template>
      <template v-if="tab === 'reports'"><div class="admin-toolbar"><h2>Последние отметки</h2><NInput v-model:value="reportUser" clearable placeholder="ID пользователя (необязательно)" /><NButton @click="reportPage = 1; safe(fetchReports)">Найти</NButton></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Пассажир</th><th>Остановка / маршрут</th><th>Загрузка</th><th>Статус / время</th><th>Проверка</th></tr></thead><tbody><tr v-for="report in reports.items" :key="report.id"><td>{{ report.user?.name }}<small>{{ report.user?.login }}</small></td><td>{{ report.stop.name }}<small>{{ report.route.number }} {{ report.isDemo ? '· DEMO' : '' }}</small></td><td>{{ report.load }}%</td><td>{{ statusLabel[report.status] }}<small>{{ dateLabel(report.createdAt) }}</small></td><td><div class="table-actions"><NButton size="small" :disabled="report.status === 'CONFIRMED'" @click="moderate(report, 'CONFIRMED')">Верно +2</NButton><NButton size="small" type="error" ghost :disabled="report.status === 'REJECTED'" @click="moderate(report, 'REJECTED')">Неверно −3</NButton></div></td></tr></tbody></table></div><p v-if="!reports.items.length" class="empty-state">Отметок нет.</p><NPagination v-model:page="reportPage" :item-count="reports.total" :page-size="25" @update:page="safe(fetchReports)" /></template>
      <template v-if="tab === 'users'"><div class="admin-toolbar"><h2>Пассажиры</h2><NInput v-model:value="userSearch" placeholder="Имя или логин" @keyup.enter="safe(fetchUsers)" /><NButton @click="safe(fetchUsers)">Найти</NButton></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Имя / логин</th><th>Роль</th><th>Рейтинг</th><th>Действия</th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td>{{ user.name }}<small>{{ user.login }}</small></td><td>{{ user.role }}</td><td>{{ user.rating }}</td><td class="table-actions"><NButton size="small" @click="adjust(user)">Изменить рейтинг</NButton><NButton size="small" @click="userHistory(user)">История отметок</NButton></td></tr></tbody></table></div><p class="muted">Первые 25 результатов. Для точного выбора используйте поиск.</p></template>
      <template v-if="tab === 'anomalies'"><h2>Сигналы за последние сутки</h2><NAlert type="info">Скачок от 50 п.п. или 5+ отметок за 10 минут — повод проверить данные. Рейтинг автоматически не меняется.</NAlert><h3>Резкие скачки</h3><div v-for="item in anomalies.jumps" :key="item.id" class="rating-entry"><strong>{{ item.previousLoad }} → {{ item.load }}%</strong><span>{{ item.userId }}</span><small>{{ dateLabel(item.createdAt) }}</small></div><p v-if="!anomalies.jumps.length" class="empty-state">Резких скачков нет.</p><h3>Частые отметки</h3><p v-for="item in anomalies.spam" :key="item.userId">{{ item.userId }} — {{ item.count }} отметок</p><p v-if="!anomalies.spam.length" class="empty-state">Подозрительной частоты нет.</p></template>
      <template v-if="tab === 'logs'"><h2>Журнал администратора</h2><div class="table-scroll"><table class="data-table"><thead><tr><th>Администратор</th><th>Действие</th><th>Объект / изменения</th><th>Время, МСК</th></tr></thead><tbody><tr v-for="log in logs" :key="log.id"><td>{{ log.admin.name }}</td><td>{{ log.action }}</td><td>{{ log.targetId }}<small>{{ JSON.stringify(log.details) }}</small></td><td>{{ dateLabel(log.createdAt) }}</td></tr></tbody></table></div><p v-if="!logs.length" class="empty-state">Действий ещё нет.</p><p class="muted">Последние 25 записей; постраничный доступ доступен в API.</p></template>
    </div>
    <NModal v-model:show="modal" preset="card" class="admin-dialog" :title="review ? 'Проверка отметки' : 'Корректировка рейтинга'"><form class="ticket-form" @submit.prevent="saveModeration"><p v-if="review">{{ review.report.user?.name }} · {{ review.report.load }}% → {{ statusLabel[review.status] }}</p><NInputNumber v-if="target" v-model:value="delta" :min="-100" :max="100" placeholder="Изменение рейтинга" /><NInput v-model:value="reason" type="textarea" placeholder="Причина (обязательно, от 3 символов)" :maxlength="500" required /><NButton type="primary" attr-type="submit" :loading="busy">Сохранить</NButton></form></NModal>
    <NModal v-model:show="ticketModal" preset="card" class="admin-dialog" :title="activeTicket?.subject"><p class="ticket-card__body">{{ activeTicket?.body }}</p><form class="ticket-form" @submit.prevent="saveTicket"><NSelect v-model:value="ticketStatus" :options="['OPEN', 'IN_PROGRESS', 'CLOSED'].map(value => ({ value, label: statusLabel[value] }))" /><NInput v-model:value="reply" type="textarea" placeholder="Ответ пассажиру" :maxlength="4000" /><NButton type="primary" attr-type="submit" :loading="busy">Сохранить</NButton></form></NModal>
  </section>
</template>
